
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_rpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_rpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.306453657042143e+00, -4.224906694375770e+00, -4.110771094044677e+00, -3.952942872884448e+00, -3.738474168989107e+00, -3.454304515113152e+00, -3.091292033229936e+00, -2.651450294096616e+00, -2.157121498971018e+00, -1.648780390122039e+00, -1.127637444864812e+00, -7.128831589689517e-01, -6.022901029018682e-01, -5.026605451409504e-01, -3.757160997648330e-01, -2.553823807932697e-01, -1.464229079360340e-01, -5.042689670088744e-02, -1.082147707426292e-02, -1.216216050001396e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


